import json

def recover_relations(response: str, atoms: dict[str, str]) -> str:
    relations = []

    # Cause-Effect relations
    if "because" in response or "caused" in response or "led to" in response or "resulted in" in response:
        # Identify the source and target of the Cause-Effect relation
        if "moral realism" in response and "human attitudes" in response:
            relations.append({"source": 5, "target": 6, "sense": "Cause-Effect", "coupling": "entailment", "strength_band": "strong"})

    # Evidence relations
    if "shows" in response or "indicates" in response or "confirms" in response or "as shown by" in response:
        # Identify the source and target of the Evidence relation
        if "A.J. Ayer" in response and "emotivism" in response:
            relations.append({"source": 7, "target": 8, "sense": "Evidence", "coupling": "entailment", "strength_band": "strong"})

    # Restatement relations
    if "that is" in response or "in other words" in response:
        # Identify the source and target of the Restatement relation
        if "cognitivism" in response and "moral judgments express beliefs" in response:
            relations.append({"source": 1, "target": 3, "sense": "Restatement", "coupling": "equivalence", "strength_band": "strong"})
        if "non-cognitivism" in response and "moral judgments express conative states" in response:
            relations.append({"source": 2, "target": 4, "sense": "Restatement", "coupling": "equivalence", "strength_band": "strong"})

    # Refutation relations
    if "cannot be squared with" in response or "rules out" in response or "it cannot have, since" in response:
        # Identify the source and target of the Refutation relation
        if "Ayer maintained" in response and "an emotivist treatment" in response:
            relations.append({"source": 8, "target": 9, "sense": "Refutation", "coupling": "contradiction", "strength_band": "strong"})
        if "Kant" in response and "Geach's appeal" in response:
            relations.append({"source": 11, "target": 9, "sense": "Refutation", "coupling": "contradiction", "strength_band": "strong"})
        if "Mackie's error theory" in response and "truth-apt" in response and "lacking truth-aptness" in response:
            relations.append({"source": 13, "target": 14, "sense": "Refutation", "coupling": "contradiction", "strength_band": "strong"})

    # Contrast relations
    if "by contrast" in response or "whereas" in response or "but" in response:
        # Identify the source and target of the Contrast relation
        if "cognitivism" in response and "non-cognitivism" in response:
            relations.append({"source": 1, "target": 2, "sense": "Contrast", "coupling": "none", "strength_band": "moderate"})

    # Concession relations
    if "although" in response or "despite" in response or "even though" in response:
        # Identify the source and target of the Concession relation
        if "error theory" in response and "cognitivism" in response:
            relations.append({"source": 13, "target": 1, "sense": "Concession", "coupling": "none", "strength_band": "weak"})

    # Alternative relations
    if "either" in response or "or" in response:
        # Identify the source and target of the Alternative relation
        if "Mackie's error theory" in response and "truth-apt" in response and "lacking truth-aptness" in response:
            relations.append({"source": 13, "target": 14, "sense": "Alternative", "coupling": "exclusive", "strength_band": "strong"})

    # Disjunction relations
    if "at least one" in response or "perhaps both" in response:
        # Identify the source and target of the Disjunction relation
        if "cognitivism" in response and "non-cognitivism" in response:
            relations.append({"source": 1, "target": 2, "sense": "Disjunction", "coupling": "co_necessity", "strength_band": "moderate"})

    # Precedence and Succession relations
    if "first" in response or "then" in response:
        # Identify the source and target of the Precedence or Succession relation
        if "Kant" in response and "Geach's appeal" in response:
            relations.append({"source": 11, "target": 9, "sense": "Precedence", "coupling": "none", "strength_band": "weak"})

    return json.dumps(relations)

